lemma coeff_linePoly_eq_homogeneousComponent_eval {F : Type*} [CommSemiring F] {n : ℕ}
    (w v : Fin n → F) (p : MvPolynomial (Fin n) F) (d : ℕ) (hd : p.totalDegree ≤ d) :
    (linePoly w v p).coeff d = MvPolynomial.eval v (MvPolynomial.homogeneousComponent d p)

protected lemma ENNReal.mul_inv_eq_iff_eq_mul {a b c: ENNReal}
  (h0 : b ≠ 0) (ha : a ≠ ∞) (hb : b ≠ ∞) (hc : c ≠ ∞) :
  a * b⁻¹ = c ↔ a = c * b
